import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"検索履歴","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 検索履歴（Search History）","slug":"_1-検索履歴-search-history","link":"#_1-検索履歴-search-history","children":[]},{"level":2,"title":"2. キーワード履歴（Keyword History）","slug":"_2-キーワード履歴-keyword-history","link":"#_2-キーワード履歴-keyword-history","children":[]},{"level":2,"title":"3. クエリ関連付け（Query Associations）","slug":"_3-クエリ関連付け-query-associations","link":"#_3-クエリ関連付け-query-associations","children":[]}],"relativePath":"ja-JP/user-guide/settings/history.md","filePath":"ja-JP/user-guide/settings/history.md","lastUpdated":1792776074000}`),a={name:`ja-JP/user-guide/settings/history.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="検索履歴" tabindex="-1">検索履歴 <a class="header-anchor" href="#検索履歴" aria-label="Permalink to “検索履歴”">​</a></h1><p>履歴設定画面では、パスごとの利用頻度、入力した検索語、および確定済みのクエリ関連付けを <strong>検索履歴</strong>・<strong>キーワード履歴</strong>・<strong>クエリ関連付け</strong> の 3 つの独立したタブで管理します。</p><h2 id="_1-検索履歴-search-history" tabindex="-1">1. 検索履歴（Search History） <a class="header-anchor" href="#_1-検索履歴-search-history" aria-label="Permalink to “1. 検索履歴（Search History）”">​</a></h2><p>実際に開いたファイル・フォルダー・アプリの利用頻度と最終起動日時を記録し、同程度の一致度を持つ候補同士の並び順を微調整します。</p><ul><li><strong>減衰付き利用頻度による微調整</strong>：よく使う項目は 90 日半減期のスコアで <strong>同じ一致グレード内</strong> で優先されますが、完全一致や明確な直接一致を追い越すことはありません。</li><li><strong>インラインウィンドウでの自動分類</strong>：ファイルダイアログのインライン検索時、現在のフォルダー内の一致項目は「現在のフォルダー」、それ以外は「全体検索」に分類されます。</li><li><strong>無効パスの自動除外</strong>：削除または移動されたパスは検索結果から自動的に除外されます。</li><li><strong>管理操作</strong>： <ul><li><strong>履歴を有効化</strong>：全体の記録スイッチ。無効時も既存の記録は保持されます。</li><li><strong>検索絞り込み・削除</strong>：絞り込み検索、<strong>N 回以下をクリア</strong>、個別削除、<strong>すべての履歴を消去</strong>を利用できます。</li><li><strong>リアルタイム更新</strong>：別の検索ウィンドウで項目を開くと一覧の回数が自動更新されます。</li></ul></li></ul><h2 id="_2-キーワード履歴-keyword-history" tabindex="-1">2. キーワード履歴（Keyword History） <a class="header-anchor" href="#_2-キーワード履歴-keyword-history" aria-label="Permalink to “2. キーワード履歴（Keyword History）”">​</a></h2><p>結果やアクションを実行したとき、またはその検索語でメインウィンドウを開いたときに実際に使用された <strong>検索文字列そのもの</strong> を記憶します。</p><ul><li><strong>ホットキーによる履歴呼び出し</strong>：クイックウィンドウで <strong><code>Alt+Up</code></strong>（前へ）/ <strong><code>Alt+Down</code></strong>（次へ）を押して過去の検索語を呼び出せます。<strong><code>Ctrl+Delete</code></strong> で表示中の履歴語を削除できます。</li><li><strong>使用回数と削除</strong>：<strong>N 回以下をクリア</strong>、個別削除、<strong>すべての履歴を消去</strong>を個別に実行できます。</li></ul><h2 id="_3-クエリ関連付け-query-associations" tabindex="-1">3. クエリ関連付け（Query Associations） <a class="header-anchor" href="#_3-クエリ関連付け-query-associations" aria-label="Permalink to “3. クエリ関連付け（Query Associations）”">​</a></h2><p>パスごとの利用頻度とは別に、確定した <strong>検索クエリ → 対象パス</strong> の学習済み関連付けを管理します。</p><ul><li><strong>3 回の手動起動による確定条件</strong>：正規化された同一クエリで <strong>3 回以上</strong> 直接選択して開いた項目のみが学習済み候補として補完され、一度きりの誤クリックによる汚染を防ぎます。</li><li><strong>自己強化ループの防止</strong>：学習補完から開いた操作は未確定カウントを増やさず、常に直接一致の後に表示されます。</li><li><strong>個別の整理・消去</strong>：パスの利用頻度を維持したまま、不要な関連付けだけを個別削除または一括消去できます。</li></ul>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};